$$ LANGUAGE plpgsql SECURITY DEFINER;

-- LOOKUP operation for organisations
CREATE OR REPLACE FUNCTION lookup_organisations(
  p_filter TEXT DEFAULT NULL,
  p_user_id INT DEFAULT NULL,
  p_limit INT DEFAULT 50
) RETURNS JSONB AS $$
DECLARE
  v_result JSONB;
BEGIN
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'value', id,
      'label', name
    ) ORDER BY name
  ), '[]'::jsonb) INTO v_result
  FROM organisations
  WHERE (p_filter IS NULL OR name ILIKE '%' || p_filter || '%')
  LIMIT p_limit;

  RETURN v_result;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- SEARCH operation for organisations
CREATE OR REPLACE FUNCTION search_organisations(
  p_filters JSONB DEFAULT '{}',
  p_search TEXT DEFAULT NULL,
  p_sort JSONB DEFAULT NULL,
  p_page INT DEFAULT 1,
  p_limit INT DEFAULT 25,
  p_user_id INT DEFAULT NULL
) RETURNS JSONB AS $$
DECLARE
  v_data JSONB;
  v_total INT;
  v_offset INT;
  v_sort_field TEXT;
  v_sort_order TEXT;
BEGIN
  v_offset := (p_page - 1) * p_limit;

  -- Extract sort parameters
  v_sort_field := COALESCE(p_sort->>'field', 'name');
  v_sort_order := COALESCE(p_sort->>'order', 'asc');

  -- Get total count
  SELECT COUNT(*) INTO v_total
  FROM organisations
  WHERE (p_search IS NULL OR (name ILIKE '%' || p_search || '%' OR description ILIKE '%' || p_search || '%'));

  -- Get data
  EXECUTE format('
    SELECT COALESCE(jsonb_agg(to_jsonb(t.*) ORDER BY %I %s), ''[]''::jsonb)
    FROM organisations t
    WHERE (CAST(%L AS TEXT) IS NULL OR (name ILIKE '%' || p_search || '%' OR description ILIKE '%' || p_search || '%'))
    LIMIT %L OFFSET %L
  ', v_sort_field, v_sort_order, p_search, p_limit, v_offset) INTO v_data;

  RETURN jsonb_build_object(
    'data', v_data,
    'total', v_total,
    'page', p_page,
    'limit', p_limit
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Graph rules: on_create on organisations
CREATE OR REPLACE FUNCTION graph_organisations_on_create(
  p_record JSONB,
  p_user_id INT
) RETURNS VOID AS $$
BEGIN
  -- Creator becomes owner
  INSERT INTO acts_for (user_id, org_id, valid_from)
  VALUES (p_user_id, (p_record->>'id'), CURRENT_DATE);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;